import json
import socket
import threading
import uuid
from datetime import datetime, timezone
from http.server import HTTPServer, BaseHTTPRequestHandler

from websockets.sync.server import ServerConnection, ServerProtocol


class ClientRegistry:
    def __init__(self):
        self._clients = {}
        self._lock = threading.Lock()

    def add(self, client_id, ws):
        with self._lock:
            self._clients[client_id] = ws

    def remove(self, client_id):
        with self._lock:
            return self._clients.pop(client_id, None)

    def get(self, client_id):
        with self._lock:
            return self._clients.get(client_id)

    def count(self):
        with self._lock:
            return len(self._clients)

    def all_items(self):
        with self._lock:
            return list(self._clients.items())

    def clear(self):
        with self._lock:
            self._clients.clear()


_registry = ClientRegistry()
_send_lock = threading.Lock()


def now_iso():
    return datetime.now(timezone.utc).isoformat()


def make_message(msg_type, payload, from_id=None):
    msg = {"type": msg_type, "payload": payload, "timestamp": now_iso()}
    if from_id:
        msg["from"] = from_id
    return json.dumps(msg)


class HealthHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health":
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.end_headers()
            response = json.dumps({"clients": _registry.count()})
            self.wfile.write(response.encode())
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, format, *args):
        pass


def handle_client(conn):
    client_id = str(uuid.uuid4())
    protocol = ServerProtocol()
    try:
        with ServerConnection(conn, protocol) as ws:
            _registry.add(client_id, ws)
            try:
                ws.send(make_message("system", {"client_id": client_id, "message": "Connected"}))

                for raw_message in ws:
                    try:
                        data = json.loads(raw_message)
                    except json.JSONDecodeError:
                        continue

                    msg_type = data.get("type", "broadcast")
                    payload = data.get("payload", {})

                    if msg_type == "broadcast":
                        msg = make_message("broadcast", payload, from_id=client_id)
                        with _send_lock:
                            for cid, cws in _registry.all_items():
                                try:
                                    cws.send(msg)
                                except Exception:
                                    _registry.remove(cid)

                    elif msg_type == "direct":
                        target = payload.get("target")
                        if target:
                            msg = make_message("direct", payload, from_id=client_id)
                            with _send_lock:
                                target_ws = _registry.get(target)
                                if target_ws:
                                    try:
                                        target_ws.send(msg)
                                    except Exception:
                                        _registry.remove(target)
            except Exception:
                pass
            finally:
                _registry.remove(client_id)
                disc_msg = make_message("system", {"client_id": client_id, "message": "Disconnected"})
                with _send_lock:
                    for cid, cws in _registry.all_items():
                        try:
                            cws.send(disc_msg)
                        except Exception:
                            _registry.remove(cid)
    except Exception:
        _registry.remove(client_id)


def start_server(host="0.0.0.0", ws_port=8765, http_port=8080):
    httpd = HTTPServer((host, http_port), HealthHandler)
    http_thread = threading.Thread(target=httpd.serve_forever, name="http-server", daemon=True)
    http_thread.start()

    sock = socket.create_server((host, ws_port), reuse_port=True)
    sock.listen()

    def accept_loop():
        try:
            while True:
                conn, addr = sock.accept()
                thread = threading.Thread(target=handle_client, args=(conn,), daemon=True)
                thread.start()
        except Exception:
            pass
        finally:
            try:
                sock.close()
            except Exception:
                pass
            httpd.shutdown()

    accept_thread = threading.Thread(target=accept_loop, name="ws-acceptor", daemon=True)
    accept_thread.start()
    return accept_thread, http_thread


if __name__ == "__main__":
    t1, t2 = start_server()
    try:
        threading.Event().wait()
    except KeyboardInterrupt:
        pass

